static constexpr int NPAIR_BOTH_II = 3;
inline const int PAIR_BOTH_II[] = {0, 8, 0, 3, 3, 8};
inline const float PAIRW_BOTH_II[] = {1.0f, 0.5f, 0.5f};

struct Panel { int n, npair; const float* anchor; const float* burial;
               const int* pair; const float* pairw; };
inline bool panels(const char* species, Panel* one, Panel* two) {
  if (!__builtin_strcmp(species, "human")) {
    *one = {N_HUMAN_I, NPAIR_HUMAN_I, ANCHOR_HUMAN_I, BURIAL_HUMAN_I,
            PAIR_HUMAN_I, PAIRW_HUMAN_I};
    *two = {N_HUMAN_II, NPAIR_HUMAN_II, ANCHOR_HUMAN_II, BURIAL_HUMAN_II,
            PAIR_HUMAN_II, PAIRW_HUMAN_II};
    return true;
  }
  if (!__builtin_strcmp(species, "mouse")) {
    *one = {N_MOUSE_I, NPAIR_MOUSE_I, ANCHOR_MOUSE_I, BURIAL_MOUSE_I,
            PAIR_MOUSE_I, PAIRW_MOUSE_I};
    *two = {N_MOUSE_II, NPAIR_MOUSE_II, ANCHOR_MOUSE_II, BURIAL_MOUSE_II,
            PAIR_MOUSE_II, PAIRW_MOUSE_II};
    return true;
  }
  if (!__builtin_strcmp(species, "mouse_c57bl6")) {
    *one = {N_MOUSE_C57BL6_I, NPAIR_MOUSE_C57BL6_I, ANCHOR_MOUSE_C57BL6_I, BURIAL_MOUSE_C57BL6_I,
            PAIR_MOUSE_C57BL6_I, PAIRW_MOUSE_C57BL6_I};
    *two = {N_MOUSE_C57BL6_II, NPAIR_MOUSE_C57BL6_II, ANCHOR_MOUSE_C57BL6_II, BURIAL_MOUSE_C57BL6_II,
            PAIR_MOUSE_C57BL6_II, PAIRW_MOUSE_C57BL6_II};
    return true;
  }
  if (!__builtin_strcmp(species, "mouse_balbc")) {
    *one = {N_MOUSE_BALBC_I, NPAIR_MOUSE_BALBC_I, ANCHOR_MOUSE_BALBC_I, BURIAL_MOUSE_BALBC_I,
            PAIR_MOUSE_BALBC_I, PAIRW_MOUSE_BALBC_I};
    *two = {N_MOUSE_BALBC_II, NPAIR_MOUSE_BALBC_II, ANCHOR_MOUSE_BALBC_II, BURIAL_MOUSE_BALBC_II,
            PAIR_MOUSE_BALBC_II, PAIRW_MOUSE_BALBC_II};
    return true;
  }
  if (!__builtin_strcmp(species, "both")) {
    *one = {N_BOTH_I, NPAIR_BOTH_I, ANCHOR_BOTH_I, BURIAL_BOTH_I,
            PAIR_BOTH_I, PAIRW_BOTH_I};
    *two = {N_BOTH_II, NPAIR_BOTH_II, ANCHOR_BOTH_II, BURIAL_BOTH_II,
            PAIR_BOTH_II, PAIRW_BOTH_II};
    return true;
  }
  return false;
}
